import { useEffect, useState } from "react"
import { createRoot } from "react-dom/client"

const dishes = [
  { id: 1, name: "Party jollof", price: 3500, soldOut: false },
  { id: 2, name: "Egusi + pounded yam", price: 4500, soldOut: false },
  { id: 3, name: "Fried rice", price: 3500, soldOut: true },
  { id: 4, name: "Zobo (50cl)", price: 700, soldOut: false },
]
const WHATSAPP = "2348000000000"
const naira = (n) => "₦" + n.toLocaleString("en-NG")
// localStorage is blocked inside this sandbox's preview, so use `storage` (a stand-in with the same methods)
const storage = (() => { try { localStorage.setItem("_t", "1"); return localStorage } catch { const m = {}; return { getItem: (k) => (k in m ? m[k] : null), setItem: (k, v) => { m[k] = String(v) } } } })()

function App() {
  const [cart, setCart] = useState(() => JSON.parse(storage.getItem("cart") || "[]"))
  const [mode, setMode] = useState("pickup")

  useEffect(() => {
    storage.setItem("cart", JSON.stringify(cart))
  }, [cart])

  function add(dish) {
    setCart((c) =>
      c.some((i) => i.id === dish.id)
        ? c.map((i) => (i.id === dish.id ? { ...i, qty: i.qty + 1 } : i))
        : [...c, { id: dish.id, name: dish.name, price: dish.price, qty: 1 }],
    )
  }

  function changeQty(id, delta) {
    setCart((c) => c.map((i) => (i.id === id ? { ...i, qty: i.qty + delta } : i)).filter((i) => i.qty > 0))
  }

  const subtotal = cart.reduce((sum, i) => sum + i.price * i.qty, 0)
  const delivery = mode === "delivery" && subtotal < 15000 ? 1000 : 0
  const total = subtotal + delivery
  const message = [
    "Order from Mama Put Kitchen:",
    ...cart.map((i) => `${i.name} × ${i.qty} = ${naira(i.price * i.qty)}`),
    `Total: ${naira(total)} (${mode})`,
  ].join("\n")

  return (
    <>
      <h1>Mama Put Kitchen</h1>
      {dishes.map((d) => (
        <article key={d.id} className="card">
          <h3>{d.name}</h3>
          <p>{naira(d.price)}</p>
          <button disabled={d.soldOut} onClick={() => add(d)}>Add</button>
        </article>
      ))}
      <ul className="cart">
        {cart.map((i) => (
          <li key={i.id}>
            <span>{i.name} × {i.qty}</span>{" "}
            <button onClick={() => changeQty(i.id, -1)}>−</button>
            <button onClick={() => changeQty(i.id, 1)}>+</button>
          </li>
        ))}
      </ul>
      <select id="mode" value={mode} onChange={(e) => setMode(e.target.value)}>
        <option value="pickup">Pickup</option>
        <option value="delivery">Delivery</option>
      </select>
      <p className="subtotal">Subtotal: {naira(subtotal)}</p>
      <p className="delivery">Delivery: {naira(delivery)}</p>
      <p className="total">Total: {naira(total)}</p>
      <a className="wa" href={`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(message)}`}>Send order on WhatsApp</a>
    </>
  )
}

createRoot(document.getElementById("root")).render(<App />)
